import { APP_NAMESPACES } from './catalog-app-namespaces';

/**
 * CATSPLIT: the browser downloads a language's catalog in parts. `site` holds what the public
 * website and the root layout render; `app` holds the namespaces only the signed-in app renders
 * (`catalog-app-namespaces.ts`, generated by `scripts/i18n/site-namespaces.mjs`). A public page
 * fetches `site` alone; any other page fetches both. The server holds every catalog whole.
 */
export const CATALOG_PARTS = ['site', 'app'] as const;

export type CatalogPart = (typeof CATALOG_PARTS)[number];

/** What a public website page needs. */
export const SITE_PARTS: readonly CatalogPart[] = ['site'];

/** What every other page needs. */
export const ALL_PARTS: readonly CatalogPart[] = CATALOG_PARTS;

const APP: ReadonlySet<string> = new Set(APP_NAMESPACES);

/** The part a message key is downloaded in, by its namespace (the prefix before the first `.`). */
export function partOfKey(key: string): CatalogPart {
  return APP.has(key.split('.')[0] ?? '') ? 'app' : 'site';
}

export function isCatalogPart(value: string): value is CatalogPart {
  return (CATALOG_PARTS as readonly string[]).includes(value);
}
